-- =========================================================================
-- ONPRINT DUBAI — 200 ADDITIONAL KEYWORDS EXPANSION (CLUSTERS A1 TO A10)
-- Target Market: Dubai, UAE | Commercial Printing, Packaging, Corporate Gifts
-- Preserves existing 150 keywords and all existing SEO tables.
-- =========================================================================

-- 1. Ensure columns exist on seo_keywords
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS category VARCHAR(150) DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS country VARCHAR(100) DEFAULT 'UAE';
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS city VARCHAR(100) DEFAULT 'Dubai';
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS current_ranking INT DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS previous_ranking INT DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS search_volume INT DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS cpc DECIMAL(8, 2) DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS competition VARCHAR(50) DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS last_checked DATE DEFAULT NULL;
ALTER TABLE seo_keywords ADD COLUMN IF NOT EXISTS ranking_change INT DEFAULT NULL;

-- 2. Insert 200 Keywords with ON DUPLICATE KEY UPDATE
ON DUPLICATE KEY UPDATE
  cluster = VALUES(cluster),
  category = COALESCE(VALUES(category), category),
  target_url = VALUES(target_url),
  target_page = COALESCE(VALUES(target_page), target_page),
  priority = VALUES(priority),
  status = VALUES(status),
  country = COALESCE(VALUES(country), country),
  city = COALESCE(VALUES(city), city),
  notes = COALESCE(VALUES(notes), notes);
